let idx=null, idxKey=null, loading=null, readyRecord=null, remoteMarker=null, remoteCheck=null, remoteKey=null, importBusy=false, revision=0, seenIds='', selectedCategory='';
const base=el('archive'), heading=el('booksArea'), current=node('section');current.id='currentArchive17';
const h=node('h2','Aktuelles Familienarchiv');const desc=node('p','Gesamtausgabe vom 26.11.2026 · Originalseiten nach Familie und Thema.');desc.className='section-intro';
