function b64(s){return Uint8Array.from(atob(s),x=>x.charCodeAt(0))}
async function openEncrypted(s,k){const v=b64(s);return unseal({iv:v.slice(0,12),data:v.subarray(12)},k)}
async function sha(b){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('')}
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ß/g,'ss');
