function candidates(){return extras.filter(x=>x.mime===mime&&(x.id===updateId||/familienbuch.*gesamtausgabe|unser familienbuch/i.test(x.name||'')))}
function addFamilies(){const select=el('family'), list=el('familyNames'), existing=new Set([...select.options].map(x=>norm(x.value)));for(const f of idx.families||[]){if(existing.has(norm(f)))continue;select.add(new Option(f,f));list.append(new Option(f,f));existing.add(norm(f))}}
async function getIndex(){if(!key)return;if(idxKey===key&&idx)return idx;if(loading&&idxKey===key)return loading;const k=key,g=generation;idxKey=k;idx=null;readyRecord=null;remoteMarker=null;remoteKey=null;seenIds='';selectedCategory='';loading=(async()=>{const v=JSON.parse(dec.decode(await openEncrypted(D.index,k)));if(v.pages.length!==276||!Array.isArray(v.groups))throw Error('Register unvollständig');if(g!==generation||k!==key)return;idx=v;addFamilies();return v})().finally(()=>{if(idxKey===k)loading=null});return loading}
async function checkCandidate(x,k){const r=await request('readonly',s=>s.get(x.id));if(!r)throw Error('Datei fehlt');const b=await unseal(r.body,k);if(await sha(b)!==idx.sha){new Uint8Array(b).fill(0);throw Error('Datei gehört nicht zur aktuellen Ausgabe')}return b}
async function detect(){const g=generation,k=key,round=++revision;readyRecord=null;for(const x of candidates()){try{const bytes=await checkCandidate(x,k);new Uint8Array(bytes).fill(0);if(g!==generation||round!==revision)return;readyRecord=x;break}catch{}}if(g===generation&&round===revision)draw()}
async function checkRemote(){if(remoteKey===key)return remoteCheck;const k=key,g=generation;remoteKey=k;remoteCheck=(async()=>{try{const r=await fetch('./fa17-ready.bin',{cache:'no-cache'});if(!r.ok)return;const b=new Uint8Array(await r.arrayBuffer());if(b.length<28||b.length>4096)return;const m=JSON.parse(dec.decode(await unseal({iv:b.slice(0,12),data:b.subarray(12)},k)));if(m.format!=='FA17-CENTRAL'||m.sha!==idx.sha||m.size!==82591087||JSON.stringify(m.parts)!==JSON.stringify(expectedParts))return;if(g===generation&&k===key)remoteMarker=m}catch{}finally{if(g===generation&&k===key)draw()}})();return remoteCheck}
async function getRemoteBody(progress){if(!remoteMarker)throw Error('Zentrale Ausgabe nicht verfügbar');const m=remoteMarker, bytes=new Uint8Array(m.size);let offset=0;for(let i=0;i<m.parts.length;i++){if(progress)progress(i,m.parts.length);const r=await fetch('./'+m.parts[i]);if(!r.ok)throw Error('Archivteil '+(i+1)+' fehlt. Bitte GitHub-Upload prüfen.');const b=new Uint8Array(await r.arrayBuffer()),expected=Math.min(4*1024*1024,bytes.length-offset);if(b.length!==expected)throw Error('Archivteil '+(i+1)+' hat eine ungültige Länge.');bytes.set(b,offset);offset+=b.length;}if(offset!==bytes.length)throw Error('Archiv nicht vollständig');return {iv:bytes.slice(0,12),data:bytes.subarray(12)}}
async function verifyBody(body,k){const plain=await unseal(body,k);if(await sha(plain)!==idx.sha){new Uint8Array(plain).fill(0);throw Error('Inhalt entspricht nicht der aktuellen Gesamtausgabe')}return plain}
async function loadBook(){const x=readyRecord,k=key;if(x)return checkCandidate(x,k);if(remoteMarker)return verifyBody(await getRemoteBody(),k);throw Error('Aktuelle Ausgabe fehlt')}
function bookButton(t,p,l='Öffnen'){const id=readyRecord?'local:'+readyRecord.id:'fa17:remote-'+updateId;return openButton(t,mime,id,loadBook,p,'Familienbuch_Gesamtausgabe.pdf',l)}
function card(t,sub,btn){const c=node('article');c.className='card';c.append(node('strong',t),node('small',sub));const a=node('div');a.className='actions';a.append(btn);c.append(a);return c}
function drawCategories(){const choices=[['','Alle Bereiche'],...idx.groups.map(g=>[g[0],g[0]]),['Statistiken','Statistiken']];catPanel.replaceChildren();for(const [v,t] of choices){const b=button(t,()=>{selectedCategory=v;draw()},true);b.setAttribute('aria-pressed',String(selectedCategory===v));catPanel.append(b)}}
function draw(){if(!key||!idx)return;results.replaceChildren();const f=el('family').value,q=el('query').value.trim(),active=!!(f||q),available=!!(readyRecord||remoteMarker);const date=base.querySelector('.archive-top small');if(date)date.textContent=readyRecord?'Archivstand 26.11.2026 · lokale Gesamtausgabe geprüft':remoteMarker?'Archivstand 26.11.2026 · zentrale Ausgabe':'Basisarchiv 24.11.2026 · Aktualisierung verfügbar';
 msg.textContent=readyRecord?'Aktuelle Gesamtausgabe gefunden und überprüft · 276 Seiten.':remoteMarker?'Zentrale Gesamtausgabe · 276 Seiten · beim Öffnen werden die verschlüsselten Archivteile geprüft.':'Aktuelle Gesamtausgabe noch nicht erkannt. Bitte das .farch-Paket installieren oder die aktuelle PDF unter Eigene Unterlagen hinzufügen.';controls.hidden=available;remotePanel.hidden=!!readyRecord||!remoteMarker;drawCategories();
 if(available){for(const [group,unused,entries] of idx.groups){if(selectedCategory&&selectedCategory!==group)continue;const grid=node('div');grid.className='grid';for(const [start,title,end] of entries){const hay=title+' '+idx.pages.slice(start-1,end).join('\n');if(!has(hay,f)||!has(hay,q))continue;grid.append(card(title,start===end?'Seite '+start:'Seiten '+start+'–'+end,bookButton(title,start)))}if(grid.children.length){results.append(node('h2',group),grid)}}
 if(active){const hits=idx.pages.map((p,i)=>({p,i})).filter(({p})=>has(p,f)&&has(p,q));const hs=node('section');hs.append(node('h2','Fundstellen in der aktuellen Ausgabe ('+hits.length+')'));if(!hits.length)hs.append(node('p','Keine passende Textstelle. Bildseiten ohne Textschicht sind nicht durchsuchbar.'));for(const {p,i} of hits.slice(0,40)){const d=node('details');const n=q?norm(p).indexOf(norm(q).split(/\s+/)[0]):0;d.append(node('summary','Seite '+(i+1)),bookButton('Fundstelle · Seite '+(i+1),i+1,'Zur Seite'),node('p',p.slice(Math.max(0,n-120),Math.max(0,n-120)+650)));hs.append(d)}if(hits.length>40)hs.append(node('p','Die ersten 40 Treffer werden angezeigt. Suche weiter eingrenzen.'));results.append(hs)}}
 const sh=idx.statisticsPages.join('\n');if((!selectedCategory||selectedCategory==='Statistiken')&&has(sh,f)&&has(sh,q)){const sg=node('div');sg.className='grid';sg.append(card('Länder, Geburtsorte und Wohnorte','Statistik vom 25.11.2026 · 5 Seiten',openButton('Länder- und Ortsstatistik',mime,'fa17-stat',async()=>{const b=await openEncrypted(D.stats,key);if(await sha(b)!==idx.statisticsSha)throw Error('Statistik beschädigt');return b},1,'Laender_und_Ortsstatistik.pdf')));results.append(node('h2','Statistiken'),sg)}
 if(!selectedCategory||selectedCategory==='Forschung'){const matching=(idx.notes||[]).filter(n=>has(n.family+' '+n.title+' '+n.text,f)&&has(n.title+' '+n.text,q));if(matching.length){const ng=node('div');ng.className='grid';for(const n of matching){const c=node('article');c.className='card';c.append(node('strong',n.title),node('small',n.status+' · '+n.date),node('p',n.text));ng.append(c)}results.append(node('h2','Ergänzende Forschungsnotizen'),ng)}}
 if(available&&!results.children.length)results.append(node('p','Keine passenden Dokumente in diesem Bereich. Filter oder Suchbegriff ändern.'));
}
function refresh(){if(!key){idx=null;idxKey=null;readyRecord=null;remoteMarker=null;remoteKey=null;results.replaceChildren();catPanel.replaceChildren();return}const g=generation;getIndex().then(v=>{if(!v||g!==generation)return;const sig=candidates().map(x=>x.id).join('|');if(sig!==seenIds){seenIds=sig;detect().catch(()=>{if(g===generation)msg.textContent='Lokale Datei konnte nicht geprüft werden.'})}else draw();checkRemote()}).catch(()=>{if(g===generation)msg.textContent='Aktualisierungsregister konnte nicht entschlüsselt werden. Das bisherige Archiv bleibt verfügbar.'})}
render=function(){oldRender();refresh()};el('family').onchange=render;el('reset').addEventListener('click',()=>{selectedCategory='';draw()});
async function saveRecord(meta,mr,body,k,g){if(g!==generation||k!==key)return;await request('readwrite',s=>s.put({id:meta.id,meta:mr,body}));if(g!==generation||k!==key)return;revision++;extras=extras.filter(x=>x.id!==meta.id);extras.push(meta);readyRecord=meta;seenIds=candidates().map(x=>x.id).join('|');render()}
async function storeRemote(){if(importBusy||!key||!remoteMarker)return;const k=key,g=generation;importBusy=true;remoteBtn.disabled=true;remoteStatus.textContent='Archiv wird geladen …';try{const body=await getRemoteBody((i,total)=>{if(g===generation)remoteStatus.textContent='Archivteil '+(i+1)+' von '+total+' wird geladen …'});const plain=await verifyBody(body,k);new Uint8Array(plain).fill(0);const meta={id:updateId,name:updateName,family:'Hentschel Stahnke Vaupel Jenner Krogull Breitenfeld Frahm Eggers',mime,archiveDate:updateDate,pages:276};const mr=await seal(new TextEncoder().encode(JSON.stringify(meta)),k);await saveRecord(meta,mr,body,k,g);if(g===generation)remoteStatus.textContent='Aktuelle Ausgabe verschlüsselt gespeichert.'}catch(e){if(g===generation)remoteStatus.textContent='Nicht vollständig gespeichert: '+e.message}finally{remoteBtn.disabled=false;importBusy=false}}
async function install(){if(importBusy||!key||!input.files[0]){if(!input.files[0])im.textContent='Bitte zuerst eine Update-Datei auswählen.';return}const k=key,g=generation;importBusy=true;ib.disabled=true;im.textContent='Update wird entschlüsselt und geprüft …';try{await getIndex();const f=input.files[0];if(f.size<72||f.size>150*1024*1024)throw Error('Ungültige Dateigröße');const header=new Uint8Array(await f.slice(0,12).arrayBuffer());if(dec.decode(header.slice(0,8))!=='FARCH17\n')throw Error('Unbekanntes Update-Format');const n=new DataView(header.buffer).getUint32(8);if(n<29||n>1048576||12+n+28>=f.size)throw Error('Ungültiger Update-Aufbau');const m=new Uint8Array(await f.slice(12,12+n).arrayBuffer()),mr={iv:m.slice(0,12),data:m.subarray(12)};const meta=JSON.parse(dec.decode(await unseal(mr,k)));if(meta.id!==updateId||meta.pages!==276||meta.mime!==mime||meta.archiveDate!==updateDate)throw Error('Diese Ausgabe wird nicht unterstützt');const b=new Uint8Array(await f.slice(12+n).arrayBuffer()),body={iv:b.slice(0,12),data:b.subarray(12)};const plain=await verifyBody(body,k);new Uint8Array(plain).fill(0);await saveRecord(meta,mr,body,k,g);if(g===generation){input.value='';im.textContent='Update erfolgreich installiert. Vorhandene Unterlagen bleiben erhalten.'}}catch(e){if(g===generation)im.textContent='Nicht installiert: '+(e.name==='OperationError'?'Archivschlüssel oder Datei passt nicht.':e.message)}finally{ib.disabled=false;importBusy=false}}
